import { COMMENT_INDEX_SQL, SCHEMA_SQL } from "./schema";
import { PG_NOW_SQL } from "./sql-compat";

/** Latest schema for an empty or already-migrated Postgres database. Idempotent. */
export function postgresBootstrapSql(): string {
  const converted = SCHEMA_SQL.replaceAll(
    "INTEGER PRIMARY KEY AUTOINCREMENT",
    "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
  )
    .replaceAll("datetime('now')", PG_NOW_SQL)
    .replaceAll(" data BLOB", " data BYTEA");
  const indexes = COMMENT_INDEX_SQL.replaceAll("datetime('now')", PG_NOW_SQL);
  return `
BEGIN;
${converted}
${indexes}
CREATE INDEX IF NOT EXISTS idx_comments_entry_path ON comments(entry_path);
-- Existing Render databases were created before Graph reply ids. CREATE TABLE IF NOT EXISTS will not add columns.
ALTER TABLE comments ADD COLUMN IF NOT EXISTS meta_sender_id TEXT;
ALTER TABLE comments ADD COLUMN IF NOT EXISTS meta_surface TEXT;
ALTER TABLE comments ADD COLUMN IF NOT EXISTS meta_post_id TEXT;
ALTER TABLE comments ADD COLUMN IF NOT EXISTS meta_post_permalink TEXT;
ALTER TABLE comments ADD COLUMN IF NOT EXISTS meta_post_caption TEXT;
ALTER TABLE comments ADD COLUMN IF NOT EXISTS commenter_key TEXT;
CREATE INDEX IF NOT EXISTS idx_comments_meta_post ON comments(meta_post_id);
-- connect-pg-simple's bundled table.sql uses WITH (OIDS=FALSE), which PostgreSQL 12+ rejects.
-- Create the session table here so the library finds it and skips that script.
CREATE TABLE IF NOT EXISTS "session" (
  "sid" varchar NOT NULL COLLATE "default" PRIMARY KEY,
  "sess" json NOT NULL,
  "expire" timestamp(6) NOT NULL
);
CREATE INDEX IF NOT EXISTS "IDX_session_expire" ON "session" ("expire");
COMMIT;
`;
}
